import subprocess, os, time, fcntl
T="/tmp/xcptest"
EXE=os.path.abspath("./executable")
# So progress goes to stderr and only when stderr is tty.
# Check verbose logs: where do they go? Earlier we saw INFO goes to stdout, ERROR to stderr. Let's verify split.
def run_split(stdout_tty, stderr_tty, args):
    import pty, os, subprocess
    stdout_master = stdout_slave = None
    stderr_master = stderr_slave = None
    if stdout_tty: stdout_master, stdout_slave = pty.openpty()
    else: stdout_pipe_r, stdout_pipe_w = os.pipe()
    if stderr_tty: stderr_master, stderr_slave = pty.openpty()
    else: stderr_pipe_r, stderr_pipe_w = os.pipe()
    p = subprocess.Popen([EXE]+args, cwd=T, stdin=subprocess.DEVNULL,
                         stdout=stdout_slave if stdout_tty else stdout_pipe_w,
                         stderr=stderr_slave if stderr_tty else stderr_pipe_w,
                         close_fds=True)
    if stdout_tty: os.close(stdout_slave)
    else: os.close(stdout_pipe_w)
    if stderr_tty: os.close(stderr_slave)
    else: os.close(stderr_pipe_w)
    import fcntl
    outs={}
    for fd, name in [(stdout_master if stdout_tty else stdout_pipe_r, "out"),
                     (stderr_master if stderr_tty else stderr_pipe_r, "err")]:
        flags=fcntl.fcntl(fd, fcntl.F_GETFL)
        fcntl.fcntl(fd, fcntl.F_SETFL, flags|os.O_NONBLOCK)
        outs[name]=(fd, b"")
    end=time.time()+4
    while time.time()<end:
        for name in list(outs.keys()):
            fd, buf = outs[name]
            try:
                d=os.read(fd, 8192)
                if d: outs[name]=(fd, buf+d)
            except OSError: pass
        if p.poll() is not None:
            time.sleep(0.3)
            for name in list(outs.keys()):
                fd, buf = outs[name]
                try:
                    while True:
                        d=os.read(fd, 8192)
                        if not d: break
                        buf+=d
                    outs[name]=(fd,buf)
                except: outs[name]=(fd,buf)
            break
        time.sleep(0.05)
    for name,(fd,buf) in outs.items(): os.close(fd)
    p.wait(timeout=5)
    return p.returncode, outs["out"][1], outs["err"][1]

import os as _os
if _os.path.exists(f"{T}/log_dest.txt"): _os.remove(f"{T}/log_dest.txt")
rc,out,err = run_split(False,False, ["-v","prog_src.txt","log_dest.txt"])
print("verbose no tty",rc,repr(out[:2000]),repr(err[:2000]))
if _os.path.exists(f"{T}/log_dest2.txt"): _os.remove(f"{T}/log_dest2.txt")
rc,out,err = run_split(True,True, ["-v","prog_src.txt","log_dest2.txt"])
print("verbose tty",rc,repr(out[:3000]),repr(err[:3000]))

# error case with -v
rc,out,err = run_split(False,False, ["-v","nonexistent_xyz","dest"])
print("err verbose",rc,repr(out[:2000]),repr(err[:2000]))
# no-clobber error with -v
open(f"{T}/e1.txt","w").write("a")
open(f"{T}/e2.txt","w").write("b")
rc,out,err = run_split(False,False, ["-v","-n","e1.txt","e2.txt"])
print("noclobber verbose",rc,repr(out[:2000]),repr(err[:2000]))
# error without -v
rc,out,err = run_split(False,False, ["-n","e1.txt","e2.txt"])
print("noclobber no verbose",rc,repr(out[:2000]),repr(err[:2000]))

# warning reflink never without -v? earlier saw it goes to stdout
rc,out,err = run_split(False,False, ["--no-progress","--reflink","never","e1.txt","warn_dest.txt"])
print("warn never no verbose",rc,repr(out[:2000]),repr(err[:2000]))

