                        let src_dbg = format!("File {{ fd: {}, path: {:?}, read: true, write: false }}", src_fd, src_path);
                        let dest_dbg = format!("File {{ fd: {}, path: {:?}, read: false, write: true }}", dest_fd, dest_path);
                        let detail = format!("Failed to reflink file and 'always' was specified: {}->{}", src_dbg, dest_dbg);
