                        log_error(&format!("Received error: {}", msg));
                        return Err((format!("Error: {}", msg), 1));
                    },
                    Err(e) => {
                        match e {
                            CopyError::Special(os_err) => return Err((format!("Error: {}", os_err), 1)),
                            CopyError::Walk(p, o) => return Err((format!("Error: IO error for operation on {}: {}\n\nCaused by:\n    {}", p, o, o), 1)),
