                        let msg = format!("Destination Exists: Destination file exists and --no-clobber is set., {}", path);
                        log_error(&format!("Received error: {}", msg));
                        return Err((format!("Error: {}", msg), 1));
                    },
                    Err(e) => return Err((format!("Error: {:?}", e), 1)),
                }
            }
        }
    }

    if is_parblock {
        log_info("Queuing complete");
        log_info("Pool complete");
    }
    log_info("Copy complete");
    // Final progress draw (ensure 100%)
    progress.completed = progress.total;
    progress.draw();
    // Progress bar in original ends without newline. Our draw also without newline. Good. But need to ensure stderr flushed? Yes.
    // For tty, should we print newline after progress? Original doesn't (ends with "remaining" no newline). Good, don't print newline.
    Ok(())
}
RS5
"}

